 "content": "def transform(grid):
    # Propagate the 2 marker downward through horizontal 8-barriers. Openings
    # in each barrier are joined across the open row above, then carry the path.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seeds = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 2]
    if not seeds:
        return g
    r, c = seeds[0]
    active = {c}
    for br in range(r + 1, h):
        if not any(v == 8 for v in g[br]):
            for c0 in active:
                if g[br][c0] == 0: g[br][c0] = 2
            continue
        holes = {j for j, v in enumerate(g[br]) if v != 8}
        if not holes:
            break
        # Connect current channels to openings in the barrier.
        points = active | holes
        lo, hi = min(points), max(points)
        above = br - 1
        for j in range(lo, hi + 1):
            if g[above][j] == 0: g[above][j] = 2
        new = {j for j in holes if lo <= j <= hi}
        for j in new:
            g[br][j] = 2
        active = new
    return g
