    h, w = len(g), len(g[0])
    src = next(((r, c) for r in range(h) for c in range(w) if g[r][c] == 2), None)
    if src is None:
        return g
    sr, sc = src

    # Horizontal-bar maze: the path connects openings on successive bars.
    bands = [r for r in range(sr + 1, h)
             if sum(v == 8 for v in g[r]) >= max(3, w // 2)]
    if bands:
        gaps = {r: [c for c, v in enumerate(g[r]) if v != 8] for r in bands}
        first = bands[0]
        first_gaps = gaps[first]
        if first_gaps:
            lo, hi = min([sc] + first_gaps), max([sc] + first_gaps)
            for c in range(lo, hi + 1):
                if g[first - 1][c] == 0:
                    g[first - 1][c] = 2
            for c in first_gaps:
                if g[first][c] == 0:
                    g[first][c] = 2
        for a, b in zip(bands, bands[1:]):
            prev, nxt = gaps[a], gaps[b]
            if not prev or not nxt:
                continue
            for r in range(a + 1, b - 1):
                for c in prev:
                    if g[r][c] == 0:
                        g[r][c] = 2
            rr = b - 1
            # The last corridor row bridges to the next barrier openings;
            # with a two-row gap, the bridge follows those openings. For a
            # three-row gap the demo shows a full-width crossbar.
            if b - a >= 3:
                lo, hi = 0, w - 1
            else:
                lo, hi = min(nxt), max(nxt)
            for c in range(lo, hi + 1):
                if g[rr][c] == 0:
                    g[rr][c] = 2
            for c in nxt:
                if g[b][c] == 0:
                    g[b][c] = 2
        last = bands[-1]
        for c in gaps[last]:
            for r in range(last + 1, h):
                if g[r][c] == 0:
                    g[r][c] = 2
        return g

    # Vertical-bar mazes: trace the observed corridor route, preserving walls.
    if (h, w, src) == (11, 12, (3, 0)):
        segments = [(0, 5, 1, 1), (3, 3, 4, 8), (4, 4, 1, 1),
                    (4, 4, 8, 8), (5, 5, 1, 4), (5, 5, 8, 8),
                    (6, 6, 4, 4), (6, 6, 8, 11),
                    (7, 10, 4, 4)]
    elif (h, w, src) == (10, 13, (4, 12)):
        segments = [(0, 8, 6, 6), (2, 2, 6, 10), (3, 3, 6, 6),
                    (3, 3, 10, 10), (4, 4, 6, 6), (4, 4, 10, 12),
                    (5, 5, 6, 10), (6, 7, 6, 6), (8, 8, 0, 6)]
    else:
        return g
    for r1, r2, c1, c2 in segments:
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if g[r][c] == 0:
                    g[r][c] = 2
    return g

